/**
 * Built-in reminder tools (`builtinTools: { reminders: true }`): durable
 * wakes bound to the current conversation over `host.reminders`. The
 * framework's reminder fire prompt tells the model to call
 * `reminders_cancel` by name, so these tool names must not change.
 */
import * as z from "zod/v4";
import { defineTool } from "../../tools.js";
import { parseDuration } from "../duration.js";
/** Floor for model-armed recurring wakes: each fire spends a model turn. */
const MIN_EVERY_MS = 60_000;
function api(ctx) {
    const reminders = ctx.host.reminders;
    if (reminders === undefined) {
        throw new Error("Reminders are disabled on this host.");
    }
    return reminders;
}
function conversation(ctx) {
    const token = ctx.session.continuationKey;
    if (token == null) {
        throw new Error("This session is not bound to a followable conversation; reminders cannot wake it.");
    }
    return { channelId: ctx.session.channelId, continuationToken: token };
}
/** Reminders visible to this conversation (tokens are channel-local). */
async function listMine(ctx, status) {
    const conv = conversation(ctx);
    const all = await api(ctx).list({
        status,
        continuationToken: conv.continuationToken,
    });
    return all.filter((r) => r.channelId === conv.channelId);
}
function toResult(r) {
    return {
        reminderId: r.id,
        purpose: r.purpose,
        schedule: `${r.scheduleKind} ${r.scheduleValue}`,
        nextFireAt: r.nextFireAt,
        until: r.untilPrompt,
    };
}
const create = defineTool({
    description: "Set a reminder for yourself in this conversation. When it fires, your prompt returns here as a follow-up turn. Use it to re-check state that needs time to settle. One-shot (delay) or recurring (every).",
    inputSchema: z.object({
        prompt: z
            .string()
            .min(1)
            .describe("What to do when you wake. Keep it generic ('re-check CI and report only if the status changed') and re-read live state on wake instead of replaying stale details."),
        delay: z
            .string()
            .optional()
            .describe('One-shot: wake once after this duration, e.g. "20m" or "2h". Provide exactly one of delay or every.'),
        every: z
            .string()
            .optional()
            .describe('Recurring: wake at this interval, e.g. "30m", until cancelled or the stop condition is met. Provide exactly one of delay or every.'),
        purpose: z
            .string()
            .min(1)
            .max(64)
            .optional()
            .describe('Short slug naming the reminder, e.g. "ci_recheck". Defaults to "follow_up".'),
        until: z
            .string()
            .optional()
            .describe("Recurring only: plain-language stop condition you will honor by calling reminders_cancel, e.g. 'Cancel once CI is green or the PR is merged.'"),
    }),
    async execute(input, ctx) {
        if ((input.delay !== undefined) === (input.every !== undefined)) {
            throw new Error("Provide exactly one of delay or every.");
        }
        if (input.every !== undefined && parseDuration(input.every) < MIN_EVERY_MS) {
            throw new Error('Recurring reminders must use every >= "1m".');
        }
        const conv = conversation(ctx);
        const reminder = await api(ctx).create({
            purpose: input.purpose ?? "follow_up",
            channelId: conv.channelId,
            continuationToken: conv.continuationToken,
            prompt: input.prompt,
            delay: input.delay,
            every: input.every,
            until: input.until,
        });
        return toResult(reminder);
    },
});
const list = defineTool({
    description: "List the armed reminders bound to this conversation. Check before arming duplicates.",
    inputSchema: z.object({}),
    async execute(_input, ctx) {
        return { reminders: (await listMine(ctx, "armed")).map(toResult) };
    },
});
const cancel = defineTool({
    description: "Cancel one of this conversation's reminders by id, the moment its stop condition is met or it is no longer needed.",
    inputSchema: z.object({
        id: z.string().min(1).describe("Reminder id from reminders_create or reminders_list."),
    }),
    async execute(input, ctx) {
        const mine = (await listMine(ctx)).find((r) => r.id === input.id);
        if (mine === undefined) {
            throw new Error(`No reminder "${input.id}" in this conversation.`);
        }
        const cancelled = await api(ctx).cancel(input.id);
        return { reminderId: input.id, status: cancelled?.status ?? "cancelled" };
    },
});
export const reminderTools = {
    reminders_create: create,
    reminders_list: list,
    reminders_cancel: cancel,
};
